/** These content-addressed variants are generated by scripts/images.mjs before build. */
export function placeImageVariants(src: string): { src: string; srcSet?: string } {
  if (!/^\/places\/photos\/[a-f0-9]{64}\.(jpg|png|webp)$/.test(src)) return { src };
  const base = src.replace('/photos/', '/photos/thumbs/v1/');
  return { src: `${base}.640.webp`, srcSet: `${base}.320.webp 320w, ${base}.640.webp 640w` };
}
